import { useState } from 'react';
import {
  Screen,
  Card,
  Stack,
  Row,
  TextField,
  Button,
  Alert,
  Badge,
  KeyBar,
} from '@nexti/ds';

type Tone = 'info' | 'success' | 'warning' | 'error';

const OPTIONS = [
  { value: '1', label: 'Pagar una orden', target: 'SCR-PAGOORD' },
  // The spec does not state which screen "Consultar una orden" opens.
  // SCR-PAGORES is assumed; confirm at gate C2.
  { value: '2', label: 'Consultar una orden', target: 'SCR-PAGORES' },
];

export default function PagoMenu({ navigate }: { navigate: (to: string) => void }) {
  const [opcion, setOpcion] = useState('');
  const [error, setError] = useState('');
  const [mensaje, setMensaje] = useState('');
  const [tone, setTone] = useState<Tone>('info');

  // Sample value for the output field FECHA (format 99/99/99)
  const fecha = '15/03/25';

  function continuar() {
    if (opcion === '') {
      const msg = 'Ingrese una opción (campo obligatorio).';
      setError(msg);
      setMensaje(msg);
      setTone('error');
      return;
    }
    const found = OPTIONS.find((o) => o.value === opcion);
    if (!found) {
      const msg = 'Opción inválida. Ingrese 1 o 2.';
      setError(msg);
      setMensaje(msg);
      setTone('error');
      return;
    }
    setError('');
    setTone('success');
    setMensaje(`Opción ${found.value} seleccionada: ${found.label}.`);
    navigate(found.target);
  }

  function salir() {
    setError('');
    setTone('info');
    setMensaje('Ha salido del menú de pagos.');
  }

  function handleChange(v: string) {
    // Numeric field, maximum length 1
    const digit = v.replace(/\D/g, '').slice(0, 1);
    setOpcion(digit);
    if (error) setError('');
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLDivElement>) {
    if (e.key === 'Enter') {
      e.preventDefault();
      continuar();
    } else if (e.key === 'F3') {
      e.preventDefault();
      salir();
    }
  }

  return (
    <Screen
      title="Banco ficticio - Pagos"
      code="PAGOMEN"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Continuar', onPress: continuar, primary: true },
            { key: 'PF3', label: 'Salir', onPress: salir },
          ]}
        />
      }
    >
      <div onKeyDown={handleKeyDown}>
        <Stack>
          <Row>
            <span>Fecha:</span>
            <div data-field="FECHA">
              <Badge>{fecha}</Badge>
            </div>
          </Row>

          <Card
            title="Menú de pagos"
            actions={
              <Row>
                <Button variant="ghost" shortcut="PF3" onClick={salir}>
                  Salir
                </Button>
                <Button variant="primary" shortcut="ENTER" onClick={continuar}>
                  Continuar
                </Button>
              </Row>
            }
          >
            <Stack>
              <ul aria-label="Opciones disponibles" style={{ margin: 0, paddingLeft: 20 }}>
                {OPTIONS.map((o) => (
                  <li key={o.value}>
                    {o.value}. {o.label}
                  </li>
                ))}
              </ul>

              <div data-field="OPCION">
                <TextField
                  label="Opción"
                  required
                  numeric
                  maxLength={1}
                  hint="Ingrese 1 para pagar una orden o 2 para consultar una orden."
                  error={error || undefined}
                  value={opcion}
                  onChange={handleChange}
                />
              </div>
            </Stack>
          </Card>

          <div data-field="MENSAJE" aria-live="polite">
            {mensaje ? <Alert tone={tone}>{mensaje}</Alert> : null}
          </div>
        </Stack>
      </div>
    </Screen>
  );
}
